import pandas as pd, numpy as np, os
from scipy.stats import spearmanr
syms=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={}
for s in syms:
    x=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).sort_values('date').set_index('date')
    D[s]=x
# common dates; signal uses day t open/close and trailing vol through t-1, forward close return t->t+1
rows=[]
for s,x in D.items():
    r=x['close'].pct_change()
    intr=x['close']/x['open']-1
    vol=r.rolling(20,min_periods=15).std().shift(1)
    f=(-intr/vol.replace(0,np.nan)).replace([np.inf,-np.inf],np.nan)
    fwd=x['close'].shift(-1)/x['close']-1
    z=pd.DataFrame({'f':f,'y':fwd}).dropna()
    z['sym']=s; rows.append(z.reset_index())
a=pd.concat(rows)
ics=[]; turnovers=[]
for dt,g in a.groupby('date'):
    if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1:
        ics.append(spearmanr(g.f,g.y).statistic)
        turnovers.append(g.set_index('sym').f.rank(pct=True).sub(0.5).abs().mean())
ic=np.array(ics)
print('dates',len(ic),'avg_n',a.groupby('date').size().loc[a.groupby('date').size()>=8].mean(),'coverage',len(a)/sum(len(x) for x in D.values()),'IC',ic.mean(),'ICIR',ic.mean()/ic.std(ddof=1),'hit',(ic>0).mean(),'turn_proxy',np.mean(turnovers))
for lo,hi in [('2020','2022-12-31'),('2023','2024-12-31'),('2025','2026-07-15')]:
 q=a[(a.date>=lo)&(a.date<=hi)]; vals=[]
 for _,g in q.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: vals.append(spearmanr(g.f,g.y).statistic)
 vals=np.array(vals); print(lo,hi,len(vals), vals.mean(), vals.mean()/vals.std(ddof=1) if len(vals)>1 else np.nan)
# decay
for h in [1,3,5,10]:
 vals=[]
 for s,x in D.items():
  r=x.close.shift(-h)/x.close-1; intr=x.close/x.open-1; vol=x.close.pct_change().rolling(20,min_periods=15).std().shift(1)
  z=pd.DataFrame({'f':-intr/vol,'y':r}).dropna(); z['date']=z.index; z['sym']=s; vals.append(z)
 q=pd.concat(vals); ii=[]
 for _,g in q.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: ii.append(spearmanr(g.f,g.y).statistic)
 ii=np.array(ii); print('decay',h,len(ii),ii.mean())

